/* Unified route and supplemental learning, separate from unit completion. */
PAGES.push('path');state.plus??={checks:{}};
let plusTab='route',plusFocusedGroup=null;
const plusUnits=l=>l==='N5'?N5_UNITS:l==='N4'?N4_UNITS:l==='N3'?N3_UNITS:N2_UNITS;
const plusUnitState=(l,u)=>l==='N5'?n5UnitState(u.id):l==='N4'?n4State(u):l==='N3'?n3State(u):n2State(u);
const plusPassed=l=>plusUnits(l).filter(u=>plusUnitState(l,u).done.includes('review')).length;
function plusFinal(l){if(l==='N5')return state.course.checks.final?.score??null;const f=state[l.toLowerCase()].final;if(!f.submitted)return null;const ids=l==='N4'?n4FinalIds():l==='N3'?n3FinalIds():n2FinalIds();return Math.round(ids.filter(id=>f.answers[id]===questionById(id).answer).length/ids.length*100);}
const plusGoals={N5:'从假名到基础生活句子',N4:'把动词变化与句型用进生活',N3:'理解段落、推断与说话意图',N2:'读懂观点、条件与论证逻辑'};
function plusOpenUnit(l,id,stage){const u=plusUnits(l).find(u=>u.id===id);if(!u)return;if(l==='N5'){n5Selected=id;n5Tab='course';n5Stage=stage||N5_STAGES.find(k=>!n5UnitState(id).done.includes(k))||'review';}else{const s=state[l.toLowerCase()];s.cursor=id;s.stage=stage||N4_STAGES.find(k=>!plusUnitState(l,u).done.includes(k))||'review';if(l==='N4'){n4FinalOpen=false;n4Guided=false;}if(l==='N3'){n3FinalOpen=false;n3Guided=false;}if(l==='N2'){n2FinalOpen=false;n2Guided=false;}}guideActive=false;persist();go('lessons',l);render();}
function plusNextHtml(l){const passed=plusPassed(l),score=plusFinal(l),u=plusUnits(l).find(u=>!plusUnitState(l,u).done.includes('review'));if(l==='N5'&&state.guide.foundation<foundationTotal)return '<button class="primary" data-page="plan" data-level="N5">先完成五十音与发音 →</button>';if(u)return `<button class="primary" data-plus-unit="${u.id}" data-plus-level="${l}">继续第 ${plusUnits(l).indexOf(u)+1} 单元 →</button>`;if(score===null||score<80)return `<button class="primary" data-plus-final="${l}">${score===null?'开始':'回看'}结课测评 →</button>`;const next=LEVELS[LEVELS.indexOf(l)+1];return next?`<button class="primary" data-plus-level="${next}">进入 ${next} 学习路线 →</button>`:'<button class="primary" data-page="real">结合官方材料继续巩固 →</button>';}
function plusGroupCard(g){const result=state.plus.checks[g.key];return `<article class="plus-check"><div><span>第 ${(g.number-1)*6+1}–${g.number*6} 单元之后</span><h3>阶段 ${g.number} · 新题应用</h3><p>${result?`最佳 ${result.score}% · ${result.score>=80?'✓ 已通过':'继续巩固'}`:'8 道新题 · 句型、阅读、听力'}</p></div><div class="toolbar"><button class="primary" data-plus-check="${g.key}">${result?'再练一次':'开始练习'} →</button><button class="secondary" data-plus-material="${g.key}">课前材料</button></div></article>`;}
function plusRouteHtml(){const l=level,passed=plusPassed(l),score=plusFinal(l);return `<div class="plus-route-grid">${[0,1,2,3].map(m=>`<section class="plus-route-block"><h3>第 ${m*6+1}–${m*6+6} 单元</h3><div class="plus-unit-list">${plusUnits(l).slice(m*6,m*6+6).map(u=>{const s=plusUnitState(l,u),done=s.done.includes('review'),started=s.done.length||s.ratings.length||Object.keys(s.answers).length;return `<button data-plus-unit="${u.id}" data-plus-level="${l}" class="${done?'passed':started?'started':''}"><span>${String(plusUnits(l).indexOf(u)+1).padStart(2,'0')}</span><strong>${esc(u.title)}</strong><span>${done?'✓ 已通过':started?'◐ 学习中':'○ 待学习'}</span></button>`;}).join('')}</div>${plusGroupCard(COURSE_PLUS_GROUPS.find(g=>g.key===l+'-'+(m+1)))}</section>`).join('')}</div><div class="plus-graduation"><h3>${l} 结课与进阶</h3><p>单元 ${passed}/24 · 结课测评 ${score===null?'未提交':score+'%'}。${passed===24&&score!==null&&score>=80?'已达到本站继续进阶的建议条件。':'建议完成单元并复核结课薄弱项，再进入下一等级。'}</p><button class="secondary" data-plus-final="${l}">打开结课测评</button><details class="learning-help"><summary>如何理解进度</summary><p>单元通过、补充课已学、阶段练习和结课成绩分别记录。补充训练不会撤销旧单元完成记录。本站条件是学习建议，不是 JLPT 官方合格标准或完整考纲覆盖率。</p></details></div>`;}
function plusLessonsHtml(){return `<div class="plus-lesson-grid">${COURSE_PLUS_LESSONS.filter(l=>l.level===level).map(l=>`<article><span class="n5-badge">${state.completed.includes(l.id)?'✓ 已学':'○ 待学习'}</span><h3>${esc(l.title)}</h3><p>${esc(l.rule)}</p><div class="toolbar"><button class="primary" data-lesson="${l.id}">讲解与例句 →</button>${favoriteButton('grammar:'+l.id)}</div></article>`).join('')}</div>`;}
function plusKanjiHtml(){if(level==='N5')return `<div class="empty-state"><h3>从 N5 的 109 个基础汉字开始</h3><p>按字认读，再放回单词与例句中。完成认读后也可以继续纸笔书写。</p><button class="primary" data-n5tab="kanji">打开 N5 汉字课程 →</button></div>`;return `<div class="toolbar"><button class="secondary" data-plus-wordquiz="${level}:0">例词读音练习 ①</button><button class="secondary" data-plus-wordquiz="${level}:1">例词读音练习 ②</button></div><div class="plus-kanji-grid">${COURSE_KANJI.filter(k=>k.level===level).map(k=>`<article><div class="plus-kanji-head"><b lang="ja">${esc(k.char)}</b><span>${esc(k.meaning)}</span></div>${k.wordIds.map(id=>{const w=words.find(w=>w.id===id);return `<div class="plus-word" data-word-id="${id}"><strong lang="ja">${esc(w.word)}</strong>${favoriteButton('word:'+id)}<details data-expand-reading="${esc(w.reading)}" data-plus-detail="${id}"><summary>回忆后展开读音与词义</summary><p lang="ja">${esc(w.reading)}</p>${romanLine(w.reading)}<p><strong>${esc(w.meaning)}</strong> <span class="pos-badge">${esc(w.pos)}</span></p><button class="secondary" data-speak="${esc(w.reading)}">▷ 读音</button><div class="toolbar"><button class="secondary" data-plus-rate="${id}" data-value="0">还不熟</button><button class="primary" data-plus-rate="${id}" data-value="1">记住了 ✓</button></div></details></div>`;}).join('')}</article>`).join('')}</div>`;}
function plusMaterialsHtml(g){return `<section class="plus-materials"><h3>${g.level} · 阶段 ${g.number} 课前材料</h3><div class="toolbar">${g.lessonIds.map(id=>`<button class="secondary" data-lesson="${id}">${esc(grammar.find(l=>l.id===id).title)}</button>`).join('')}</div><article><h3>阅读</h3><p class="japanese-text" lang="ja">${esc(g.reading.text)}</p><details><summary>中文对照</summary><p>${esc(g.reading.translation)}</p></details></article><article><h3>听力</h3><button class="primary" data-speak="${esc(g.listening.text)}">▷ 播放对话</button><button class="secondary" data-stop-audio="true">停止</button><details><summary>听后查看原文与中文</summary><p class="japanese-text" lang="ja">${esc(g.listening.text)}</p><p>${esc(g.listening.translation)}</p></details></article><button class="primary" data-plus-check="${g.key}">完成准备，进入 8 题练习 →</button></section>`;}
function renderPath(){const l=level;if(plusFocusedGroup&&!plusFocusedGroup.startsWith(l+'-'))plusFocusedGroup=null;return title('','学习路线 · '+l,'')+`<section class="container page-section plus-page"><div class="plus-levels">${LEVELS.map(x=>`<button data-plus-level="${x}" aria-pressed="${x===l}" class="${x===l?'selected':''}"><strong>${x}</strong><span>${plusPassed(x)}/24 单元</span></button>`).join('')}</div><div class="plus-hero"><div><h2>${plusGoals[l]}</h2><p>词汇 → 句型 → 阅读 → 听力 → 复习；每 6 单元加入一组新题。</p></div>${plusNextHtml(l)}</div><div class="toolbar plus-tabs" role="group" aria-label="学习路线栏目">${[['route','单元路线'],['grammar','语法辨析'],['kanji','汉字与读音'],['checks','阶段新题']].map(([k,name])=>`<button class="${plusTab===k?'primary':'secondary'}" data-plus-tab="${k}" aria-pressed="${plusTab===k}">${name}</button>`).join('')}</div>${plusTab==='route'?plusRouteHtml():plusTab==='grammar'?plusLessonsHtml():plusTab==='kanji'?plusKanjiHtml():`${COURSE_PLUS_GROUPS.filter(g=>g.level===l).map(plusGroupCard).join('')}${plusFocusedGroup?plusMaterialsHtml(COURSE_PLUS_GROUPS.find(g=>g.key===plusFocusedGroup)):''}`}</section>`;}
function plusOrigin(id){const reading=COURSE_PLUS_READINGS.find(q=>q.id===id);if(reading){const w=words.find(w=>w.id===reading.word);return{word:w.id,level:w.level,label:w.word};}const extra=COURSE_PLUS_QUESTIONS.find(q=>q.id===id);if(extra)return extra.lesson?{lesson:extra.lesson,label:grammar.find(g=>g.id===extra.lesson).title}:{group:extra.group,label:extra.title};const g=grammar.find(g=>g.id===id);if(g)return{lesson:id,label:g.title};for(const l of LEVELS)for(const u of plusUnits(l)){for(const st of ['reading','listening'])if(u[st].ids.includes(id))return{level:l,unit:u.id,stage:st,label:u.title};if(u.wordIds.includes(id))return{level:l,unit:u.id,stage:l==='N5'?(u.wordIds.indexOf(id)<10?'words1':'words2'):'words',label:u.title};}const w=words.find(w=>w.id===id);if(w)return {word:w.id,level:w.level,label:w.word};return null;}
function plusWeakLinks(ids){const origins=[...new Map(ids.map(id=>[JSON.stringify(plusOrigin(id)),{id,origin:plusOrigin(id)}])).values()].filter(x=>x.origin);return origins.length?`<section class="container plus-weak"><h3>回到对应内容</h3><div class="toolbar">${origins.slice(0,8).map(({id,origin})=>`<button class="secondary" data-plus-origin="${id}">${esc(origin.label)} →</button>`).join('')}</div></section>`:'';}
const plusPreviousPractice=renderPractice;renderPractice=function(){const html=plusPreviousPractice();return state.activeQuiz?html:html+plusWeakLinks(Object.keys(state.mistakes).filter(id=>questionById(id)?.level===level));};
const plusPreviousHome=renderHome;renderHome=function(){return plusPreviousHome().replace('<h2>我的学习路线</h2>','<h2>我的学习路线</h2><button class="more" data-page="path">完整路线与阶段检查 →</button>');};
const plusPreviousLessons=renderLessons;renderLessons=function(isGrammar=false){return plusPreviousLessons(isGrammar)+(isGrammar?'':`<section class="container plus-entry"><button class="secondary" data-page="path">学习路线 · 语法辨析 · 阶段新题 →</button></section>`);};
const plusPreviousPlan=renderPlan;renderPlan=function(){const due=dueWords().length,wrong=Object.keys(state.mistakes).filter(id=>questionById(id)?.level===level).length;return plusPreviousPlan()+`<section class="container plus-entry"><h3>温习再前进</h3><div class="toolbar"><button class="secondary" data-plus-due ${due?'':'disabled'}>到期词汇 ${due} 个</button><button class="secondary" data-plus-mistakes ${wrong?'':'disabled'}>待巩固错题 ${wrong} 道</button><button class="secondary" data-page="path">学习路线与阶段检查 →</button></div></section>`;};
const plusPreviousRender=render;render=function(scroll=true){if(page!=='path')return plusPreviousRender(scroll);$('#view').innerHTML=renderPath();$('#levelTabs').innerHTML=LEVELS.map(l=>`<button data-level="${l}" class="${l===level?'selected':''}" aria-pressed="${l===level}">${l}</button>`).join('');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',false));if(scroll)window.scrollTo({top:0,behavior:'instant'});};
const plusPreviousFinish=finishQuiz;finishQuiz=function(){const z=state.activeQuiz,g=z&&COURSE_PLUS_GROUPS.find(g=>g.level===z.level&&g.ids.length===z.ids.length&&g.ids.every(id=>z.ids.includes(id))),wrong=z?z.ids.filter((id,i)=>z.answers[i]!==questionById(id).answer):[];if(g&&z.answers.length===g.ids.length){const score=Math.round((g.ids.length-wrong.length)/g.ids.length*100),old=state.plus.checks[g.key];if(!old||score>=old.score)state.plus.checks[g.key]={score,date:dateKey()};if(score>=80)state.textDone=[...new Set([...state.textDone,...g.reading.questions.map(q=>q.id),...g.listening.questions.map(q=>q.id)])];}plusPreviousFinish();if(g){$('#view').innerHTML+=`<section class="container plus-entry"><button class="primary" data-page="path">返回学习路线 →</button><button class="secondary" data-plus-check="${g.key}">再练这组新题</button></section>`+plusWeakLinks(wrong);} };
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.plusUnit){plusOpenUnit(d.plusLevel,d.plusUnit);return;}
 if(d.plusLevel&&LEVELS.includes(d.plusLevel)){plusFocusedGroup=null;plusTab='route';go('path',d.plusLevel);render();}
 if(d.plusTab&&['route','grammar','kanji','checks'].includes(d.plusTab)){plusTab=d.plusTab;render(false);}
 if(d.plusMaterial){const g=COURSE_PLUS_GROUPS.find(g=>g.key===d.plusMaterial);if(!g)return;plusTab='checks';plusFocusedGroup=g.key;go('path',g.level);render(false);}
 if(d.plusCheck){const g=COURSE_PLUS_GROUPS.find(g=>g.key===d.plusCheck);if(!g)return;if(state.activeQuiz){go('practice',state.activeQuiz.level);toast('先完成或结束当前练习，已有答案已保留。');return;}guideActive=false;state.activeQuiz={level:g.level,mode:'exam',ids:shuffled(g.ids),answers:[],index:0};persist();go('practice',g.level);render();}
 if(d.plusWordquiz){if(state.activeQuiz){go('practice',state.activeQuiz.level);toast('先完成或结束当前练习。');return;}const [l,n]=d.plusWordquiz.split(':'),ids=COURSE_KANJI.filter(k=>k.level===l).flatMap(k=>k.wordIds).slice(Number(n)*16,Number(n)*16+16).map(id=>COURSE_PLUS_READINGS.find(q=>q.word===id).id);if(!LEVELS.includes(l)||!ids.length)return;guideActive=false;state.activeQuiz={level:l,mode:'vocab',ids:shuffled(ids),answers:[],index:0};persist();go('practice',l);render();}
 if(d.plusRate){const w=words.find(w=>w.id===d.plusRate);if(!w||!COURSE_KANJI.some(k=>k.wordIds.includes(w.id)))return;const old=state.wordReviews[w.id],box=d.value==='1'?old?.last===dateKey()?Math.max(old.box,1):Math.min((old?.box||0)+1,6):0;state.wordReviews[w.id]={box,due:box?afterDays([1,3,7,14,30,60][box-1]):dateKey(),last:dateKey()};touch('vocab');persist();b.textContent=d.value==='1'?'✓ 已记住':'↺ 待巩固';}
 if(d.plusOrigin){const origin=plusOrigin(d.plusOrigin);if(!origin)return;if(origin.lesson)openLesson(origin.lesson);else if(origin.group){const g=COURSE_PLUS_GROUPS.find(g=>g.key===origin.group);plusTab='checks';plusFocusedGroup=g.key;go('path',g.level);render();}else if(origin.word){guideActive=false;wordReviewMode='all';go('vocab',origin.level);search=words.find(w=>w.id===origin.word).word;wordCursor=Math.max(0,visibleWords().findIndex(w=>w.id===origin.word));render();}else plusOpenUnit(origin.level,origin.unit,origin.stage);}
 if(d.plusDue!==undefined){guideActive=false;wordReviewMode='due';go('vocab',level);render();}
 if(d.plusMistakes!==undefined){guideActive=false;go('practice',level);if(!state.activeQuiz)startQuiz('review');render();}
 if(d.plusFinal){const l=d.plusFinal;if(!LEVELS.includes(l))return;guideActive=false;if(l==='N5'){go('lessons',l);if(state.course.exam?.key==='final'){n5Tab='checks';n5Selected=null;persist();render();}else n5StartExam('final');}else{if(l==='N4')n4FinalOpen=true;if(l==='N3')n3FinalOpen=true;if(l==='N2')n2FinalOpen=true;go('lessons',l);render();}}
});
fromHash();
